// RM-4 slice builder (idempotent): 1-4 "nest of the parasite tree", field only (boss room y<32 belongs to the boss lead).
// `Unity -batchmode -executeMethod Exoduser.Rm4SliceBuilder.Run -quit` builds Remodel/CH1_4/RM4_Slice.unity from Data/ch1_4_build.json (generated by tools/rm4/plan.mjs from the web oracle):
// Terrain (procedural non-repeating colour map + root-ridge relief), toxic river ribbons on the outer rim + one pool on the L3 island, procedural lump blockout on the blocked islands and the outer rim,
// root-flow decal ribbons converging on the heart/boss gate, light pools (Pool_Hell_NN / Pool_Toxic_NN, nearest-8 culler), hell shafts, Cinemachine LOOK-001, NavMesh from the Core walk grid.
// `Capture -outDir <dir> -cuts start,heart,gate,top [-capsule 1]`, `Wedge` (sight-wedge capsule rays), `Fps -out <json>`.
// Coordinates: web px -> world x = px/100, z = -px_y/100 (1 tile = 40 px = 0.4 u). Core (Runtime/Core) and RM-1 files are not touched (only read).
namespace Exoduser
{
    public static class Rm4SliceBuilder
    {
        const string Root = "Assets/Exoduser/Remodel/CH1_4";
        const string R1 = "Assets/Exoduser/Remodel/CH1_1";   // RM-1 shared textures (read only: no import-setting changes)
        const string ScenePath = Root + "/RM4_Slice.unity";
        const string GenDir = Root + "/Generated";
        // Padded terrain (tiles): the web grid is x0..199, y0..199. Terrain adds a 24-tile rim west/east, 16 south, and ends at y16 in the north (slice window y>=32 + view margin).
        const int TX0 = -24, TY0 = 16, TX1 = 224, TY1 = 216;
        // Judged slice window (tiles, end exclusive): x0..199, y32..199.
        const int WX0 = 0, WX1 = 200, WY0 = 32, WY1 = 200;
        const float T = 0.4f, TerrainH = 4f, BaseY = -0.5f, Pitch = 0.85f, DistU = 14f;
        const int HRes = 1025, ARes = 512, PPT = 12;

        [Serializable] class BMass { public string kind, id, web; public int size, bx0, by0, bx1, by1; public float cx, cy, hMax; }
        [Serializable] class BPool { public string name, kind, label; public float x, y, r; }
        [Serializable] class BShaft { public float x0, y0, x1, y1; }
        [Serializable] class BLine { public string id; public bool ridge, trunk; public float w0, w1; public float[] xs, ys; }
        [Serializable] class BRiver { public string id; public float half; public float[] xs, ys; }
        [Serializable] class BToxic { public string id; public int[] tx, ty; }
        [Serializable] class BuildData { public string[] rows; public int[] window; public BMass[] masses; public BPool[] pools; public BShaft[] shafts; public BLine[] flow; public BRiver[] rivers; public BToxic[] toxic; }

        static BuildData build; static string[] walkRows; static int[,] distWalk, distBlock; static Terrain terrain;
        static List<Vector2[]> riverCL = new List<Vector2[]>(); static List<(Vector2 a, Vector2 b)> riverSegs = new List<(Vector2, Vector2)>(); static List<(Vector2 a, Vector2 b)> ridgeSegs = new List<(Vector2, Vector2)>();
                static readonly Color LightHell = Hex("#b0281c"), LightToxic = Hex("#b7b54a"), ShadowCol = Hex("#120c0a"), FogLow = Hex("#2a1a16");
        static Color Hex(string h) { ColorUtility.TryParseHtmlString(h, out var c); return c; }
        static bool Walk(int x, int y) { return x >= 0 && y >= 0 && x < 200 && y < 200 && walkRows[y][x] == '0'; }
        static float Hash(int x, int y) { unchecked { uint h = (uint)(x * 374761393 + y * 668265263); h = (h ^ (h >> 13)) * 1274126177u; return ((h ^ (h >> 16)) & 0xffff) / 65535f; } }
        static Vector3 W(float tx, float ty, float y = 0f) { return new Vector3(tx * T, y, -ty * T); }
        static float Smooth(float a, float b, float x) { x = Mathf.Clamp01((x - a) / (b - a)); return x * x * (3 - 2 * x); }
        static int OutDist(int tx, int ty)   // chebyshev distance outside the 200x200 web grid, plus the distance of the clamped grid tile
        {
            int dx = Mathf.Max(0, Mathf.Max(-tx, tx - 199)), dy = Mathf.Max(0, Mathf.Max(-ty, ty - 199));
            int cx = Mathf.Clamp(tx, 0, 199), cy = Mathf.Clamp(ty, 0, 199);
            return distWalk[cy, cx] + Mathf.Max(dx, dy);
        }
        static float GroundY(float wx, float wz) { return terrain.SampleHeight(new Vector3(wx, 0, wz)) + terrain.transform.position.y; }
        static string Out(string name) { var d = "I:/EXODUSER-Storage/rm4/out"; Directory.CreateDirectory(d); return d + "/" + name; }

        // ---- footprints of 3D masses (XZ world), used to prove no lump/ribbon covers a Core walk tile
        struct FP { public string kind; public float cx, cz, hw, hd, yaw; public bool circle; }
        static readonly List<FP> fps = new List<FP>();
        static readonly List<Vector2[]> ribbonQuads = new List<Vector2[]>();
        static bool InFP(FP f, float px, float pz, float margin)
        {
            float dx = px - f.cx, dz = pz - f.cz;
            if (f.circle) return dx * dx + dz * dz < (f.hw + margin) * (f.hw + margin);
            float c = Mathf.Cos(f.yaw * Mathf.Deg2Rad), s = Mathf.Sin(f.yaw * Mathf.Deg2Rad);
            float lx = dx * c - dz * s, lz = dx * s + dz * c;
            return Mathf.Abs(lx) < f.hw + margin && Mathf.Abs(lz) < f.hd + margin;
        }
        static bool FpHitsWalk(FP f)
        {
            float r = f.circle ? f.hw : Mathf.Sqrt(f.hw * f.hw + f.hd * f.hd);
            int x0 = Mathf.FloorToInt((f.cx - r) / T) - 1, x1 = Mathf.CeilToInt((f.cx + r) / T) + 1, y0 = Mathf.FloorToInt((-f.cz - r) / T) - 1, y1 = Mathf.CeilToInt((-f.cz + r) / T) + 1;
            for (int ty = y0; ty <= y1; ty++) for (int tx = x0; tx <= x1; tx++)
                    if (Walk(tx, ty) && InFP(f, (tx + .5f) * T, -(ty + .5f) * T, 0.04f)) return true;
            return false;
        }
        static bool InTri(Vector2 p, Vector2 a, Vector2 b, Vector2 c)
        {
            float d1 = (p.x - b.x) * (a.y - b.y) - (a.x - b.x) * (p.y - b.y), d2 = (p.x - c.x) * (b.y - c.y) - (b.x - c.x) * (p.y - c.y), d3 = (p.x - a.x) * (c.y - a.y) - (c.x - a.x) * (p.y - a.y);
            bool neg = d1 < 0 || d2 < 0 || d3 < 0, pos = d1 > 0 || d2 > 0 || d3 > 0; return !(neg && pos);
        }
        static List<Vector2> Chaikin(List<Vector2> p, int it)
        {
            for (int n = 0; n < it; n++)
            {
                var o = new List<Vector2> { p[0] };
                for (int i = 0; i + 1 < p.Count; i++) { o.Add(.75f * p[i] + .25f * p[i + 1]); o.Add(.25f * p[i] + .75f * p[i + 1]); }
                o.Add(p[p.Count - 1]); p = o;
            }
            return p;
        }
        static List<Vector2> Resample(float[] xs, float[] ys, float step)
        {
            var o = new List<Vector2>(); float carry = 0f; o.Add(new Vector2(xs[0], ys[0]));
            for (int i = 0; i + 1 < xs.Length; i++)
            {
                var a = new Vector2(xs[i], ys[i]); var b = new Vector2(xs[i + 1], ys[i + 1]); float len = (b - a).magnitude; if (len < 1e-4f) continue;
                float t = step - carry;
                while (t <= len) { o.Add(a + (b - a) * (t / len)); t += step; }
                carry = len - (t - step);
            }
            o.Add(new Vector2(xs[xs.Length - 1], ys[ys.Length - 1])); return o;
        }
        static float DistToSegs(List<(Vector2 a, Vector2 b)> segs, float X, float Y)
        {
            float best = 1e9f; var p = new Vector2(X, Y);
            foreach (var (a, b) in segs)
            {
                var ab = b - a; float t = Mathf.Clamp01(Vector2.Dot(p - a, ab) / Mathf.Max(1e-5f, ab.sqrMagnitude)); float d = (p - (a + ab * t)).sqrMagnitude; if (d < best) best = d;
            }
            return Mathf.Sqrt(best);
        }
        static float RiverDist(float X, float Y) { if (X > 12f && X < 188f) return 1e9f; return DistToSegs(riverSegs, X, Y); }   // rivers hug the west/east rim only (x<-3 / x>202); anything inside x12..188 is farther than 9 tiles

        static void Load()
        {
            build = JsonUtility.FromJson<BuildData>(File.ReadAllText(Root + "/Data/ch1_4_build.json")); walkRows = build.rows;
            distWalk = Bfs(true); distBlock = Bfs(false);
            riverCL.Clear(); riverSegs.Clear(); ridgeSegs.Clear();
            foreach (var r in build.rivers)
            {   // dense along the polyline, clipped to the padded terrain, smoothed
                var dense = Resample(r.xs, r.ys, 3f); var raw = new List<Vector2>();
                foreach (var p in dense) if (p.x > TX0 + 1 && p.x < TX1 - 1 && p.y > TY0 + 1 && p.y < TY1 - 1) raw.Add(p);
                if (raw.Count < 2) continue; var cl = Chaikin(raw, 2); riverCL.Add(cl.ToArray());
                for (int i = 0; i + 1 < cl.Count; i++) riverSegs.Add((cl[i], cl[i + 1]));
            }
            foreach (var l in build.flow) if (l.ridge) for (int i = 0; i + 1 < l.xs.Length; i++) ridgeSegs.Add((new Vector2(l.xs[i], l.ys[i]), new Vector2(l.xs[i + 1], l.ys[i + 1])));
        }
        static int[,] Bfs(bool toWalk)
        {
            var d = new int[200, 200]; var q = new Queue<(int, int)>();
            for (int y = 0; y < 200; y++) for (int x = 0; x < 200; x++) { bool src = toWalk ? Walk(x, y) : !Walk(x, y); d[y, x] = src ? 0 : -1; if (src) q.Enqueue((x, y)); }
            while (q.Count > 0) { var (x, y) = q.Dequeue(); for (int dy = -1; dy <= 1; dy++) for (int dx = -1; dx <= 1; dx++) { int nx = x + dx, ny = y + dy; if (nx < 0 || ny < 0 || nx >= 200 || ny >= 200 || d[ny, nx] >= 0) continue; d[ny, nx] = d[y, x] + 1; q.Enqueue((nx, ny)); } }
            return d;
        }

        public static void Run()
        {
            Directory.CreateDirectory(GenDir); Directory.CreateDirectory(Root + "/Materials"); AssetDatabase.Refresh();
            Load(); fps.Clear(); ribbonQuads.Clear(); wedge.Clear();
            var mats = MakeMaterials();
            var td = BuildTerrainData();
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            var world = new GameObject("World");
            var tgo = Terrain.CreateTerrainGameObject(td); tgo.name = "Terrain"; tgo.transform.SetParent(world.transform, false);
            tgo.transform.position = new Vector3(TX0 * T, BaseY, -TY1 * T);
            terrain = tgo.GetComponent<Terrain>(); terrain.drawInstanced = true; terrain.heightmapPixelError = 3f; terrain.basemapDistance = 400f;

            BuildToxic(world.transform, mats);
            BuildBlockout(world.transform, mats);
            BuildBgCards(world.transform, mats);
            BuildDecals(world.transform, mats);
            FgMat = mats.FgRoots;
            BuildLighting(mats);
            WalkOverlap();
            var marker = BuildCamera();
            var pools = GameObject.Find("Pools"); var cull = pools.AddComponent<Rm4PoolLightCuller>(); cull.focus = marker; cull.Refresh(marker.position);
            BuildNavMesh(world.transform);
            HeroLayerReport();
            WriteWedgeCandidates();
            EditorSceneManager.SaveScene(scene, ScenePath);
            AssetDatabase.SaveAssets();
            Debug.Log("[RM4] slice built: " + ScenePath);
        }

        // ---------------------------------------------------------------- materials
        class Mats { public Material Toxic, Mass, Bark, FgRoots, BgTree, Shaft1, Shaft2, Strand, StrandRidge; public Dictionary<string, Material> Decal = new Dictionary<string, Material>(); }
        static Material Mat(string path, Shader sh, Action<Material> init)
        {
            var m = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (m == null) { m = new Material(sh); AssetDatabase.CreateAsset(m, path); }
            m.shader = sh; init(m); EditorUtility.SetDirty(m); return m;
        }
        static void OwnTexSettings(string path, bool clamp, int max, bool alpha, bool mips)
        {
            var imp = AssetImporter.GetAtPath(path) as TextureImporter; if (imp == null) return;
            imp.wrapMode = clamp ? TextureWrapMode.Clamp : TextureWrapMode.Repeat; imp.maxTextureSize = max; imp.alphaIsTransparency = alpha; imp.mipmapEnabled = mips;
            if (imp.textureCompression == TextureImporterCompression.CompressedHQ) imp.textureCompression = TextureImporterCompression.Compressed;
            imp.SaveAndReimport();
        }
        static Mats MakeMaterials()
        {
            var mats = new Mats(); var lit = Shader.Find("Universal Render Pipeline/Lit");
            mats.Toxic = Mat(Root + "/Materials/M_ToxicFlow4.mat", Shader.Find("EXODUSER/ToxicFlow"), m => { });
            var massTex = AssetDatabase.LoadAssetAtPath<Texture2D>(R1 + "/Materials/Mass/mass_v01.png"); var nrmTex = AssetDatabase.LoadAssetAtPath<Texture2D>(R1 + "/Materials/Mass/mass_v01_normal.png");
            Action<Material, Color, float> massInit = (m, tint, smooth) => { m.SetTexture("_BaseMap", massTex); m.SetColor("_BaseColor", tint); m.SetTexture("_BumpMap", nrmTex); m.SetFloat("_BumpScale", 1f); m.EnableKeyword("_NORMALMAP"); m.SetFloat("_Smoothness", smooth); m.SetFloat("_Metallic", 0f); };
            mats.Mass = Mat(Root + "/Materials/M_RootMass4.mat", lit, m => massInit(m, new Color(.60f, .54f, .50f), .10f));
            mats.Bark = Mat(Root + "/Materials/M_CursedBark4.mat", lit, m => massInit(m, new Color(.40f, .34f, .33f), .06f));
            var cardSh = Shader.Find("EXODUSER/FgCard");
            var fgTex = ProcCard(GenDir + "/card_fg_roots.png", 41, true); var bgTex = ProcCard(GenDir + "/card_bg_tree.png", 53, false);
            mats.FgRoots = Mat(Root + "/Materials/M_FgRoots4.mat", cardSh, m => { m.SetTexture("_MainTex", fgTex); m.SetColor("_Color", new Color(.045f, .028f, .022f, .80f)); });
            mats.BgTree = Mat(Root + "/Materials/M_BgTree4.mat", cardSh, m => { m.SetTexture("_MainTex", bgTex); m.SetColor("_Color", new Color(.20f, .17f, .19f, .55f)); });
            var shaft = Shader.Find("EXODUSER/LightShaft");
            mats.Shaft1 = Mat(Root + "/Materials/M_Shaft4_1.mat", shaft, m => { m.SetColor("_Color", LightHell); m.SetFloat("_Intensity", 0.42f); m.SetFloat("_Phase", 0.4f); });
            mats.Shaft2 = Mat(Root + "/Materials/M_Shaft4_2.mat", shaft, m => { m.SetColor("_Color", LightHell); m.SetFloat("_Intensity", 0.34f); m.SetFloat("_Phase", 2.1f); });
            var decal = Shader.Find("EXODUSER/GroundDecal");
            EnsureWetTexture(); var strandTex = EnsureStrandTexture();
            foreach (var n in new[] { "blood", "blood_cracked", "blood_drag", "blood_drops", "root", "root_branch", "root_tangle", "bone", "bone_ribs", "bone_skull" })
            {
                var tex = AssetDatabase.LoadAssetAtPath<Texture2D>(R1 + "/Materials/Decals/decal_" + n + ".png");
                mats.Decal[n] = Mat(Root + "/Materials/M_Decal4_" + n + ".mat", decal, m => { m.SetTexture("_MainTex", tex); m.SetColor("_Tint", Color.white); m.SetFloat("_Alpha", 0.9f); });
            }
            var wetTex = AssetDatabase.LoadAssetAtPath<Texture2D>(GenDir + "/decal_wet4.png");
            mats.Decal["wet"] = Mat(Root + "/Materials/M_Decal4_wet.mat", decal, m => { m.SetTexture("_MainTex", wetTex); m.SetColor("_Tint", Hex("#5a5020")); m.SetFloat("_Alpha", 0.9f); });
            mats.Strand = Mat(Root + "/Materials/M_RootStrand4.mat", decal, m => { m.SetTexture("_MainTex", strandTex); m.SetColor("_Tint", new Color(.85f, .80f, .74f, 1f)); m.SetFloat("_Alpha", 0.9f); m.SetFloat("_Lit", 0.8f); });
            mats.StrandRidge = Mat(Root + "/Materials/M_RootStrandRidge4.mat", decal, m => { m.SetTexture("_MainTex", strandTex); m.SetColor("_Tint", new Color(1f, .93f, .82f, 1f)); m.SetFloat("_Alpha", 0.95f); m.SetFloat("_Lit", 0.8f); });
            return mats;
        }
        // soft irregular wet blob (alpha mask), procedural
        static void EnsureWetTexture()
        {
            var p = GenDir + "/decal_wet4.png"; const int S = 256; var t = new Texture2D(S, S, TextureFormat.RGBA32, false);
            for (int y = 0; y < S; y++) for (int x = 0; x < S; x++)
            {
                float u = (x - S / 2f) / (S / 2f), v = (y - S / 2f) / (S / 2f), r = Mathf.Sqrt(u * u + v * v);
                float n = Mathf.PerlinNoise(x * .035f + 3.1f, y * .035f + 9.4f) * .55f + Mathf.PerlinNoise(x * .09f, y * .09f) * .25f;
                float a = Mathf.Clamp01((0.95f - r + (n - .4f) * .8f) * 1.7f); a *= a; a *= Smooth(0.92f, 0.62f, r) * (1f - Smooth(0.86f, 1f, Mathf.Max(Mathf.Abs(u), Mathf.Abs(v))));
                t.SetPixel(x, y, new Color(1, 1, 1, a));
            }
            File.WriteAllBytes(p, t.EncodeToPNG()); UnityEngine.Object.DestroyImmediate(t); AssetDatabase.ImportAsset(p); OwnTexSettings(p, true, 256, true, false);
        }
        // root strand: two twisted strands (u across, v along, tileable along v), warm bone-brown, soft edges, ragged side rootlets
        static Texture2D EnsureStrandTexture()
        {
            var p = GenDir + "/decal_root_strand4.png"; const int SW = 128, SH = 256; var px = new Color32[SW * SH];
            for (int y = 0; y < SH; y++) for (int x = 0; x < SW; x++)
            {
                float u = (x + .5f) / SW, v = (y + .5f) / SH; float ph = v * Mathf.PI * 2f * 2f;
                float c1 = .5f + .17f * Mathf.Sin(ph), c2 = .5f + .17f * Mathf.Sin(ph + Mathf.PI), w = .17f;
                float a1 = Smooth(w, w * .35f, Mathf.Abs(u - c1)), a2 = Smooth(w, w * .35f, Mathf.Abs(u - c2));
                float over = Mathf.Cos(ph) > 0 ? 1f : 0f;   // which strand lies on top at this v
                float a = Mathf.Max(a1, a2);
                float rootlet = Mathf.PerlinNoise(u * 9f + 3f, Mathf.Repeat(v, 1f) * 14f) > .72f ? Smooth(0.5f, 0.34f, Mathf.Abs(u - .5f)) * .35f : 0f;   // faint side hairs
                a = Mathf.Max(a, rootlet);
                float shade = .62f + .38f * (over > 0 ? (a1 > a2 ? 1f : .75f) : (a2 > a1 ? 1f : .75f));
                float grain = .85f + .15f * Mathf.Sin(v * 90f + u * 17f) * Mathf.PerlinNoise(u * 6f, v * 11f);
                float k = shade * grain; var c = Color.Lerp(new Color(.18f, .12f, .09f), new Color(.50f, .39f, .29f), Mathf.Clamp01(k));
                px[y * SW + x] = new Color32((byte)(c.r * 255), (byte)(c.g * 255), (byte)(c.b * 255), (byte)(Mathf.Clamp01(a) * 255));
            }
            var t = new Texture2D(SW, SH, TextureFormat.RGBA32, false); t.SetPixels32(px); File.WriteAllBytes(p, t.EncodeToPNG()); UnityEngine.Object.DestroyImmediate(t); AssetDatabase.ImportAsset(p); OwnTexSettings(p, false, 256, true, true);
            return AssetDatabase.LoadAssetAtPath<Texture2D>(p);
        }

        // ---------------------------------------------------------------- terrain
        class TexData { public Color32[] px; public int w, h; public float mean, std; }
        static TexData LoadReadable(string assetPath)
        {
            var t = new Texture2D(2, 2, TextureFormat.RGBA32, false); t.LoadImage(File.ReadAllBytes(assetPath)); var d = new TexData { px = t.GetPixels32(), w = t.width, h = t.height };
            double s = 0, s2 = 0; foreach (var c in d.px) { double l = (c.r + c.g + c.b) / 765.0; s += l; s2 += l * l; }
            d.mean = (float)(s / d.px.Length); d.std = Mathf.Max(0.02f, (float)Math.Sqrt(Math.Max(0, s2 / d.px.Length - (double)d.mean * d.mean))); UnityEngine.Object.DestroyImmediate(t); return d;
        }
        static float Lum(TexData d, float u, float v)   // bilinear luminance, repeat
        {
            u = u - Mathf.Floor(u); v = v - Mathf.Floor(v); float fx = u * d.w - .5f, fy = v * d.h - .5f; int x0 = Mathf.FloorToInt(fx), y0 = Mathf.FloorToInt(fy); float ax = fx - x0, ay = fy - y0;
            float L(int x, int y) { var c = d.px[((y % d.h + d.h) % d.h) * d.w + ((x % d.w + d.w) % d.w)]; return (c.r + c.g + c.b) / 765f; }
            return Mathf.Lerp(Mathf.Lerp(L(x0, y0), L(x0 + 1, y0), ax), Mathf.Lerp(L(x0, y0 + 1), L(x0 + 1, y0 + 1), ax), ay);
        }
        static int BD(int x, int y) { if (x < 0 || y < 0 || x >= 200 || y >= 200) return 0; return Mathf.Min(distBlock[y, x], Mathf.Min(Mathf.Min(x + 1, 200 - x), Mathf.Min(y + 1, 200 - y))); }
        static float BlockDistF(float X, float Y)
        {
            float fx = X - .5f, fy = Y - .5f; int x0 = Mathf.FloorToInt(fx), y0 = Mathf.FloorToInt(fy); float ax = fx - x0, ay = fy - y0;
            return Mathf.Lerp(Mathf.Lerp(BD(x0, y0), BD(x0 + 1, y0), ax), Mathf.Lerp(BD(x0, y0 + 1), BD(x0 + 1, y0 + 1), ax), ay);
        }
        // W1: one non-repeating colour map for the whole terrain, procedural from the confirmed PAINTGROUND floors + palette + root web (denser/thicker to the north) + blood veins + AO along blocked tiles
        static string BuildColormap()
        {
            int W0 = (TX1 - TX0) * PPT, H0 = (TY1 - TY0) * PPT; var pxs = new Color32[W0 * H0]; var mask = new float[W0 * H0];
            foreach (var l in build.flow)
            {
                int n = l.xs.Length; float phase = Hash(l.id.Length, (int)(l.xs[0] * 7)) * 6.28f;
                for (int i = 0; i + 1 < n; i++)
                {
                    var a = new Vector2(l.xs[i], l.ys[i]); var b = new Vector2(l.xs[i + 1], l.ys[i + 1]); float len = (b - a).magnitude * PPT; int steps = Mathf.Max(1, Mathf.CeilToInt(len / 0.5f));
                    for (int s = 0; s <= steps; s++)
                    {
                        float tt = (i + s / (float)steps) / (n - 1f); var p = Vector2.Lerp(a, b, s / (float)steps); float w = (l.w0 + (l.w1 - l.w0) * tt) * (l.ridge ? 1.15f : 1f); float r = Mathf.Max(1.2f, w * .5f * PPT);
                        float cx = (p.x - TX0) * PPT, cy = (TY1 - p.y) * PPT; int ri = Mathf.CeilToInt(r) + 1;
                        for (int yy = -ri; yy <= ri; yy++) for (int xx = -ri; xx <= ri; xx++)
                            {
                                int X = Mathf.RoundToInt(cx) + xx, Y = Mathf.RoundToInt(cy) + yy; if (X < 0 || Y < 0 || X >= W0 || Y >= H0) continue;
                                float d = Mathf.Sqrt(xx * xx + yy * yy); if (d > r) continue; float v = Mathf.Clamp01((r - d) / Mathf.Max(1f, r * .6f)); int ix = Y * W0 + X; if (v > mask[ix]) mask[ix] = v;
                            }
                    }
                }
            }
            var f1 = LoadReadable(R1 + "/Materials/Ground/floor_v01b.png"); var f2 = LoadReadable(R1 + "/Materials/Ground/floor_v02b.png"); var f3 = LoadReadable(R1 + "/Materials/Ground/floor_v03b.png");
            Color lo = Hex("#1f1312"), hi = Hex("#4a2c28"), bruise = Hex("#3b2a2e"), vein = Hex("#4a1612"), rootD = Hex("#2e2118"), rootL = Hex("#5a4636");
            for (int y = 0; y < H0; y++) for (int x = 0; x < W0; x++)
                {
                    float X = TX0 + (x + .5f) / PPT, Y = TY1 - (y + .5f) / PPT;
                    float wu = X * T, wv = Y * T;   // world metres
                    float warp = (Mathf.PerlinNoise(X * .06f + 4f, Y * .06f + 8f) - .5f) * 2.2f, warp2 = (Mathf.PerlinNoise(X * .05f + 31f, Y * .05f + 2f) - .5f) * 2.2f;
                    float n1 = Mathf.PerlinNoise(X * .035f + 11f, Y * .035f + 7f), n2 = Mathf.PerlinNoise(X * .08f + 3f, Y * .08f + 19f);
                    float wa = Smooth(.32f, .62f, n1), wb = (1f - wa) * Smooth(.38f, .68f, n2), wc = 1f - wa - wb;
                    float la = (Lum(f1, (wu + warp) / 3.2f, (wv + warp2) / 3.2f) - f1.mean) / (4f * f1.std), lb = (Lum(f2, (wu + warp2 * .7f) / 2.6f, (wv - warp) / 2.6f) - f2.mean) / (4f * f2.std), lc = (Lum(f3, (wu - warp) / 3.6f, (wv + warp2) / 3.6f) - f3.mean) / (4f * f3.std);
                    float Ln = Mathf.Clamp01(.5f + wa * la + wb * lb + wc * lc);
                    var col = Color.Lerp(lo, hi, Mathf.Pow(Ln, 1.15f));
                    float n3 = Mathf.PerlinNoise(X * .06f + 50f, Y * .06f + 20f); col = Color.Lerp(col, bruise, Smooth(.55f, .78f, n3) * .5f);
                    float rv = Mathf.Abs(Mathf.PerlinNoise(X * .09f + 90f, Y * .09f + 40f) * 2f - 1f); float vm = (1f - Smooth(0f, .07f, rv)) * Smooth(.45f, .7f, n2); col = Color.Lerp(col, vein, vm * .6f);
                    float m = mask[y * W0 + x];
                    if (m > 0f)
                    {
                        float st = .5f + .5f * Mathf.Sin(X * 5.3f + Y * 3.1f + Mathf.PerlinNoise(X * .9f, Y * .9f) * 6f); var rc = Color.Lerp(rootD, rootL, st * .85f); col = Color.Lerp(col, rc, Mathf.Clamp01(m * 1.25f) * .88f);
                    }
                    float bd = BlockDistF(X, Y); float ao = Mathf.Lerp(.55f, 1f, Smooth(0f, 2.6f, bd)); if (bd <= 0.01f) ao = .5f;
                    col *= ao; col.a = 1f; pxs[y * W0 + x] = (Color32)col;
                }
            var tex = new Texture2D(W0, H0, TextureFormat.RGBA32, false); tex.SetPixels32(pxs); var path = GenDir + "/ch1_4_colormap.png"; File.WriteAllBytes(path, tex.EncodeToPNG()); UnityEngine.Object.DestroyImmediate(tex);
            AssetDatabase.ImportAsset(path); OwnTexSettings(path, true, 4096, false, true); Debug.Log("[RM4] colormap " + W0 + "x" + H0); return path;
        }
        static TerrainData BuildTerrainData()
        {
            var cm = BuildColormap(); var layers = new List<TerrainLayer>();
            TerrainLayer TL(string name, string tex, Vector2 size)
            {
                var path = GenDir + "/TL_" + name + ".terrainlayer"; var l = AssetDatabase.LoadAssetAtPath<TerrainLayer>(path);
                if (l == null) { l = new TerrainLayer(); AssetDatabase.CreateAsset(l, path); }
                l.diffuseTexture = AssetDatabase.LoadAssetAtPath<Texture2D>(tex); l.tileSize = size; l.tileOffset = Vector2.zero; l.smoothness = 0f; l.metallic = 0f; EditorUtility.SetDirty(l); return l;
            }
            float sx = (TX1 - TX0) * T, sz = (TY1 - TY0) * T;
            layers.Add(TL("Colormap", cm, new Vector2(sx, sz)));
            layers.Add(TL("Floor1", R1 + "/Materials/Ground/floor_v01b.png", new Vector2(3.2f, 3.2f)));
            layers.Add(TL("Floor2", R1 + "/Materials/Ground/floor_v02b.png", new Vector2(2.6f, 2.6f)));
            layers.Add(TL("Floor3", R1 + "/Materials/Ground/floor_v03b.png", new Vector2(3.6f, 3.6f)));
            var path2 = GenDir + "/RM4_Terrain.asset"; AssetDatabase.DeleteAsset(path2);
            var td = new TerrainData { heightmapResolution = HRes, alphamapResolution = ARes, baseMapResolution = 512 };
            td.size = new Vector3(sx, TerrainH, sz);
            AssetDatabase.CreateAsset(td, path2);
            td.terrainLayers = layers.ToArray();
            td.SetHeights(0, 0, ComputeHeights());
            td.SetAlphamaps(0, 0, ComputeAlpha());
            AddGrass(td);
            return td;
        }
        // toxic pool on the L3 island: body tiles (not shore, not the trunk zone) sink, shore tiles stay low, the 3x3 trunk zone around the island centre stays raised for the maw lump
        static readonly Dictionary<(int, int), string> poolRole = new Dictionary<(int, int), string>();
        static Dictionary<(int, int), float> PoolTileH()
        {
            var o = new Dictionary<(int, int), float>(); poolRole.Clear();
            foreach (var pl in build.toxic)
            {
                float cxs = 0, cys = 0; for (int i = 0; i < pl.tx.Length; i++) { cxs += pl.tx[i] + .5f; cys += pl.ty[i] + .5f; } cxs /= pl.tx.Length; cys /= pl.tx.Length; int ctx = Mathf.FloorToInt(cxs), cty = Mathf.FloorToInt(cys);
                for (int i = 0; i < pl.tx.Length; i++)
                {
                    int tx = pl.tx[i], ty = pl.ty[i]; bool shore = Walk(tx + 1, ty) || Walk(tx - 1, ty) || Walk(tx, ty + 1) || Walk(tx, ty - 1);
                    bool trunk = Mathf.Abs(tx - ctx) <= 1 && Mathf.Abs(ty - cty) <= 1;
                    string role = trunk ? "trunk" : shore ? "shore" : "body"; poolRole[(tx, ty)] = role;
                    o[(tx, ty)] = role == "trunk" ? 0.30f : role == "shore" ? 0.03f : -0.28f;
                }
            }
            return o;
        }
        static float TileH(int tx, int ty, Dictionary<(int, int), float> pool)
        {
            if (pool.TryGetValue((tx, ty), out var ph)) return ph;
            if (Walk(tx, ty)) return 0f;
            int d = (tx < 0 || ty < 0 || tx >= 200 || ty >= 200) ? OutDist(tx, ty) : distWalk[ty, tx];
            return Mathf.Min(1.5f, 0.28f * (d - 0.2f)) * (0.75f + 0.5f * Hash(tx, ty));
        }
        static float[,] ComputeHeights()
        {
            var pool = PoolTileH(); var h = new float[HRes, HRes];
            for (int i = 0; i < HRes; i++) for (int j = 0; j < HRes; j++)
                {
                    float X = TX0 + (TX1 - TX0) * (j / (float)(HRes - 1)), Y = TY1 - (TY1 - TY0) * (i / (float)(HRes - 1));
                    float fx = X - .5f, fy = Y - .5f; int x0 = Mathf.FloorToInt(fx), y0 = Mathf.FloorToInt(fy); float ax = fx - x0, ay = fy - y0;
                    h[i, j] = Mathf.Lerp(Mathf.Lerp(TileH(x0, y0, pool), TileH(x0 + 1, y0, pool), ax), Mathf.Lerp(TileH(x0, y0 + 1, pool), TileH(x0 + 1, y0 + 1, pool), ax), ay);
                }
            for (int pass = 0; pass < 2; pass++) { BoxBlur(h, 6, true); BoxBlur(h, 6, false); }
            var ridgeNear = new bool[200, 200]; for (int ty = 0; ty < 200; ty++) for (int tx = 0; tx < 200; tx++) ridgeNear[ty, tx] = Walk(tx, ty) && DistToSegs(ridgeSegs, tx + .5f, ty + .5f) < 3.2f;
            const float RidgeH = 0.04f;   // low root ridges: visual relief only, never a collider / lump; judged separately from the walk-cover count. 0.04u max: the runtime does not lift the hero to the terrain height (NativeGame.Point z=0), so a walk-tile ridge buries the feet by up to RidgeH (map lead decision 10-28); the lost relief comes from normal map / decals
            for (int i = 0; i < HRes; i++) for (int j = 0; j < HRes; j++)
                {
                    float X = TX0 + (TX1 - TX0) * (j / (float)(HRes - 1)), Y = TY1 - (TY1 - TY0) * (i / (float)(HRes - 1));
                    float v = h[i, j] + 0.014f * (Mathf.PerlinNoise(X * .33f, Y * .33f) - .5f) * 2f;
                    float d = RiverDist(X, Y);
                    if (d < 3.0f)
                    {
                        float w = Smooth(2.6f, 1.2f, d);
                        v = Mathf.Lerp(v, -0.42f, w);
                        v += 0.05f * Smooth(1.7f, 2.4f, d) * Smooth(3.0f, 2.5f, d);   // bank lip
                    }
                    if (X >= 0f && X < 200f && Y >= 0f && Y < 200f && ridgeNear[Mathf.FloorToInt(Y), Mathf.FloorToInt(X)] && Walk(Mathf.FloorToInt(X), Mathf.FloorToInt(Y)))
                    {
                        float rd = DistToSegs(ridgeSegs, X, Y); if (rd < 1.6f) v += RidgeH * Mathf.Exp(-(rd * rd) / (2f * .42f * .42f));
                    }
                    h[i, j] = Mathf.Clamp01((v - BaseY) / TerrainH);
                }
            return h;
        }
        static void BoxBlur(float[,] h, int r, bool horiz)
        {
            var tmp = new float[HRes, HRes];
            for (int i = 0; i < HRes; i++) { float sum = 0; int n = 0; for (int k = -r; k <= r; k++) { int jj = Mathf.Clamp(k, 0, HRes - 1); sum += horiz ? h[i, jj] : h[jj, i]; n++; }
                for (int j = 0; j < HRes; j++) { if (horiz) tmp[i, j] = sum / n; else tmp[j, i] = sum / n; int add = Mathf.Clamp(j + r + 1, 0, HRes - 1), rem = Mathf.Clamp(j - r, 0, HRes - 1); sum += (horiz ? h[i, add] : h[add, i]) - (horiz ? h[i, rem] : h[rem, i]); } }
            Array.Copy(tmp, h, tmp.Length);
        }
        static float[,,] ComputeAlpha()
        {
            var a = new float[ARes, ARes, 4];
            for (int i = 0; i < ARes; i++) for (int j = 0; j < ARes; j++)
                {
                    float X = TX0 + (TX1 - TX0) * (j / (float)(ARes - 1)), Y = TY1 - (TY1 - TY0) * (i / (float)(ARes - 1));
                    float d = RiverDist(X, Y); float wet = Smooth(6f, 2f, d);
                    float n1 = Mathf.PerlinNoise(X * .17f, Y * .17f), n2 = Mathf.PerlinNoise(X * .29f + 40f, Y * .29f + 17f);
                    float detail = 0.17f;                                   // W1: detail layers stay a low share on top of the one colour map
                    float w1 = detail * n1 * (1 - wet * .5f), w2 = detail * n2 * (1 - wet * .5f), w3 = detail * (0.25f + wet * 1.2f);
                    float w0 = 1f; float s = w0 + w1 + w2 + w3; a[i, j, 0] = w0 / s; a[i, j, 1] = w1 / s; a[i, j, 2] = w2 / s; a[i, j, 3] = w3 / s;
                }
            return a;
        }

        // ---------------------------------------------------------------- toxic river ribbons (outer rim) + pool surface (L3 island)
        static Mesh SaveMesh(Mesh m, string name) { var p = GenDir + "/" + name + ".asset"; AssetDatabase.DeleteAsset(p); AssetDatabase.CreateAsset(m, p); return m; }
        static void BuildToxic(Transform parent, Mats mats)
        {
            var root = new GameObject("Toxic"); root.transform.SetParent(parent, false);
            for (int ri = 0; ri < riverCL.Count; ri++)
            {
                var cl = riverCL[ri]; int N = cl.Length; float half = build.rivers[Mathf.Min(ri, build.rivers.Length - 1)].half; const float level = -0.21f;
                var vs = new List<Vector3>(); var uvs = new List<Vector2>(); var tris = new List<int>(); float along = 0f; var prevW = new Vector2[2];
                for (int i = 0; i < N; i++)
                {
                    var tg = (cl[Mathf.Min(i + 1, N - 1)] - cl[Mathf.Max(i - 1, 0)]).normalized; var nm = new Vector2(-tg.y, tg.x); var c = cl[i];
                    var l = c + nm * half; var r = c - nm * half; if (i > 0) along += (c - cl[i - 1]).magnitude * T;
                    vs.Add(W(l.x, l.y, level)); vs.Add(W(r.x, r.y, level)); uvs.Add(new Vector2(-half * T, along)); uvs.Add(new Vector2(half * T, along));
                    if (i > 0) { int b = (i - 1) * 2; tris.AddRange(new[] { b, b + 2, b + 1, b + 1, b + 2, b + 3 }); ribbonQuads.Add(new[] { prevW[0], prevW[1], new Vector2(r.x * T, -r.y * T), new Vector2(l.x * T, -l.y * T) }); }
                    prevW[0] = new Vector2(l.x * T, -l.y * T); prevW[1] = new Vector2(r.x * T, -r.y * T);
                }
                var m = new Mesh { name = "River4_" + ri, indexFormat = IndexFormat.UInt32 }; m.SetVertices(vs); m.SetUVs(0, uvs); m.SetTriangles(tris, 0); m.RecalculateNormals(); m.RecalculateBounds(); SaveMesh(m, "River4_" + ri);
                var go = new GameObject("River_" + (ri == 0 ? "W" : "E")); go.transform.SetParent(root.transform, false);
                go.AddComponent<MeshFilter>().sharedMesh = m; var mr = go.AddComponent<MeshRenderer>(); mr.sharedMaterial = mats.Toxic; mr.shadowCastingMode = ShadowCastingMode.Off;
            }
            foreach (var pl in build.toxic)
            {
                var vs = new List<Vector3>(); var uvs = new List<Vector2>(); var tris = new List<int>();
                for (int i = 0; i < pl.tx.Length; i++)
                {
                    int tx = pl.tx[i], ty = pl.ty[i]; if (!poolRole.TryGetValue((tx, ty), out var role) || role != "body") continue; int b = vs.Count; float y = -0.12f;
                    vs.Add(W(tx, ty, y)); vs.Add(W(tx + 1, ty, y)); vs.Add(W(tx, ty + 1, y)); vs.Add(W(tx + 1, ty + 1, y));
                    foreach (var v in new[] { vs[b], vs[b + 1], vs[b + 2], vs[b + 3] }) uvs.Add(new Vector2(v.x, v.z) * 0.9f);
                    tris.AddRange(new[] { b, b + 1, b + 2, b + 2, b + 1, b + 3 });
                }
                var m = new Mesh { name = "Pool4_" + pl.id }; m.SetVertices(vs); m.SetUVs(0, uvs); m.SetTriangles(tris, 0); m.RecalculateNormals(); m.RecalculateBounds(); SaveMesh(m, "Pool4_" + pl.id);
                var go = new GameObject("Pool_" + pl.id); go.transform.SetParent(root.transform, false);
                go.AddComponent<MeshFilter>().sharedMesh = m; var mr = go.AddComponent<MeshRenderer>(); mr.sharedMaterial = mats.Toxic; mr.shadowCastingMode = ShadowCastingMode.Off;
            }
        }

        // ---------------------------------------------------------------- sight wedge (LOOK-001): h <= 0.9 + tan(pitch) * D, D = from the lump's north end to the nearest walkable tile centre north of it (u)
        class WedgeRec { public string name, kind; public float h, dU, hMaxU; public int tx = -1, ty = -1; public Vector3 pos; }
        static readonly List<WedgeRec> wedge = new List<WedgeRec>();
        static float WedgeD(float cx, float cz, float r, out int wtx, out int wty)   // returns D in u, 99 when no walk tile lies north inside the column band
        {
            float yn = -(cz + r) / T; float cxT = cx / T, band = r / T + 0.5f; float best = 1e9f; wtx = -1; wty = -1;
            for (int x = Mathf.FloorToInt(cxT - band); x <= Mathf.CeilToInt(cxT + band); x++)
                for (int ty = Mathf.FloorToInt(yn); ty >= 0; ty--) { if (Walk(x, ty)) { float d = yn - (ty + .5f); if (d < best) { best = d; wtx = x; wty = ty; } break; } }
            return best >= 1e8f ? 99f : Mathf.Max(0f, best * T);
        }
        static float HMax(float dU) { return dU >= 99f ? 5.0f : 0.9f + Mathf.Tan(Pitch) * dU; }

        // ---------------------------------------------------------------- procedural lump blockout on blocked islands + outer rim
        static void BuildBlockout(Transform parent, Mats mats)
        {
            var root = new GameObject("Blockout"); root.transform.SetParent(parent, false); var rnd = new System.Random(4403); int count = 0;
            foreach (var m in build.masses)
            {
                float cxT = m.cx, cyT = m.cy; var wp = W(cxT, cyT); float gy = GroundY(wp.x, wp.z);
                float hwT = Mathf.Max(0.35f, (m.bx1 - m.bx0 + 1) * 0.5f * T * 0.95f), hdT = Mathf.Max(0.35f, (m.by1 - m.by0 + 1) * 0.5f * T * 0.95f);
                bool toxicIsland = false; foreach (var tp in build.toxic) { for (int i = 0; i < tp.tx.Length; i++) if (tp.tx[i] == Mathf.FloorToInt(cxT) && tp.ty[i] == Mathf.FloorToInt(cyT)) toxicIsland = true; }
                float h, tileM = 2.4f;
                if (m.kind == "landmark") h = Mathf.Lerp(.95f, 1.12f, (float)rnd.NextDouble()); else if (m.kind == "knot_large") h = Mathf.Lerp(.7f, 1.1f, (float)rnd.NextDouble()); else h = Mathf.Lerp(.5f, .9f, (float)rnd.NextDouble());
                if (toxicIsland) { hwT = 0.62f; hdT = 0.62f; h = 1.0f; }       // L3: a flesh-maw lump on the 3x3 trunk zone, toxic body ring around it
                float yaw = (float)rnd.NextDouble() * 360f; var fp = new FP { kind = "mass", cx = wp.x, cz = wp.z, hw = hwT, hd = hdT, yaw = yaw }; int shrink = 0;
                while (FpHitsWalk(fp) && shrink++ < 10) { fp.hw *= .88f; fp.hd *= .88f; }
                if (FpHitsWalk(fp)) { Debug.LogWarning("[RM4] mass skipped (no room) " + m.id + " " + cxT + "," + cyT); continue; }
                float rr = Mathf.Sqrt(fp.hw * fp.hw + fp.hd * fp.hd); float dU = WedgeD(wp.x, wp.z, rr, out int wtx, out int wty); float hm = Mathf.Min(m.hMax > 0 ? m.hMax : 9f, HMax(dU));
                h = Mathf.Min(h, 0.97f * hm);
                string nm = "Mass_" + (string.IsNullOrEmpty(m.id) ? (count).ToString("00") : m.id) + (string.IsNullOrEmpty(m.web) ? "" : "_" + m.web); count++;
                MakeLump(nm, root.transform, new Vector3(wp.x, gy, wp.z), yaw, fp.hw, fp.hd, h, 4000 + count * 13, mats.Mass, tileM, false); fps.Add(fp);
                wedge.Add(new WedgeRec { name = nm, kind = m.kind, h = h, dU = dU, hMaxU = hm, tx = wtx, ty = wty, pos = new Vector3(wp.x, gy, wp.z) });
            }
            BuildRim(root.transform, mats, ref count);
            FillIslands(root.transform, mats, ref count);
            Debug.Log("[RM4] blockout lumps=" + count);
        }
        // outer rim: west/east/south of the web grid (the north grid edge continues past the slice, so no rim there). Two layers of lumps; heights follow the wedge where a walk tile lies north.
        static void BuildRim(Transform root, Mats mats, ref int count)
        {
            var rnd = new System.Random(4404); var placed = new List<Vector2>(); int n0 = count;
            foreach (var (dmin, dmax, sep, hLo, hHi) in new[] { (3, 6, 6.2f, 1.2f, 2.8f), (7, 14, 8.5f, 2.6f, 4.6f), (15, 23, 10f, 3.4f, 5.4f) })
            {
                var cand = new List<Vector2>();
                for (int ty = TY0 + 1; ty < TY1; ty++) for (int tx = TX0 + 1; tx < TX1; tx++)
                    {
                        if (tx >= 0 && tx <= 199 && ty <= 199) continue;      // inside the web grid (walk or island): never a rim lump
                        int dx = Mathf.Max(0, Mathf.Max(-tx, tx - 199)), dy = Mathf.Max(0, ty - 199); int d = Mathf.Max(dx, dy); if (d < dmin || d > dmax) continue;
                        if (RiverDist(tx + .5f, ty + .5f) < 4.6f) continue; cand.Add(new Vector2(tx + .5f, ty + .5f));
                    }
                for (int i = cand.Count - 1; i > 0; i--) { int j = rnd.Next(i + 1); (cand[i], cand[j]) = (cand[j], cand[i]); }
                foreach (var c in cand)
                {
                    bool ok = true; foreach (var p in placed) if ((p - c).magnitude < sep) { ok = false; break; }
                    if (!ok) continue; placed.Add(c);
                    float w = Mathf.Lerp(2.6f, 4.4f, (float)rnd.NextDouble()), dp = Mathf.Lerp(2.2f, 3.8f, (float)rnd.NextDouble()), hh = Mathf.Lerp(hLo, hHi, (float)rnd.NextDouble());
                    float yaw = (float)rnd.NextDouble() * 360f; var wp = W(c.x, c.y); float gy = GroundY(wp.x, wp.z);
                    var fp = new FP { kind = "rim", cx = wp.x, cz = wp.z, hw = w * .5f, hd = dp * .5f, yaw = yaw };
                    if (FpHitsWalk(fp)) { placed.RemoveAt(placed.Count - 1); continue; }
                    float rr = Mathf.Sqrt(fp.hw * fp.hw + fp.hd * fp.hd); float dU = WedgeD(wp.x, wp.z, rr, out int wtx, out int wty); hh = Mathf.Min(hh, 0.97f * HMax(dU));
                    string nm = "Rim_" + (count - n0).ToString("000"); count++;
                    MakeLump(nm, root, new Vector3(wp.x, gy, wp.z), yaw, fp.hw, fp.hd, hh, 6000 + count * 11, mats.Mass, 2.4f, false); fps.Add(fp);
                    if (wtx >= 0) wedge.Add(new WedgeRec { name = nm, kind = "rim", h = hh, dU = dU, hMaxU = HMax(dU), tx = wtx, ty = wty, pos = new Vector3(wp.x, gy, wp.z) });
                }
            }
            Debug.Log("[RM4] rim lumps=" + (count - n0));
        }
        static void AddMeshObj(string name, Transform parent, Mesh m, Material mat)
        {
            var go = new GameObject(name); go.transform.SetParent(parent, false); go.AddComponent<MeshFilter>().sharedMesh = m; var r = go.AddComponent<MeshRenderer>(); r.sharedMaterial = mat; r.shadowCastingMode = ShadowCastingMode.On;
        }
        static void MakeLump(string name, Transform parent, Vector3 pos, float yaw, float hw, float hd, float h, int seed, Material mat, float tile, bool trunk)
        {
            var rnd = new System.Random(seed); var lp = new LumpP { hw = hw, hd = hd, h = h, seed = seed, tile = tile };
            lp.n = Mathf.Lerp(2.1f, 3.4f, (float)rnd.NextDouble()); lp.body = Mathf.Lerp(.68f, .9f, (float)rnd.NextDouble()); lp.top = Mathf.Lerp(.45f, .8f, (float)rnd.NextDouble()); lp.flareT = Mathf.Lerp(.2f, .4f, (float)rnd.NextDouble()); lp.lobes = 3 + rnd.Next(4); lp.lobeAmp = Mathf.Lerp(.14f, .28f, (float)rnd.NextDouble()); lp.lobeDecay = Mathf.Lerp(.3f, .5f, (float)rnd.NextDouble()); lp.noise = Mathf.Lerp(.10f, .22f, (float)rnd.NextDouble()); lp.lean = Mathf.Lerp(.05f, .26f, (float)rnd.NextDouble()); lp.topBump = Mathf.Lerp(.12f, .26f, (float)rnd.NextDouble()); lp.jag = 0f; lp.dome = Mathf.Lerp(.16f, .34f, (float)rnd.NextDouble()); lp.top = Mathf.Min(lp.top, .66f);
            var go = new GameObject(name); go.transform.SetParent(parent, false); go.transform.SetPositionAndRotation(pos, Quaternion.Euler(0, yaw, 0));
            go.AddComponent<MeshFilter>().sharedMesh = LumpMesh(lp); var r = go.AddComponent<MeshRenderer>(); r.sharedMaterial = mat; r.shadowCastingMode = ShadowCastingMode.On;
        }
        class LumpP { public float dome = 0f, hw, hd, h, n = 2.8f, body = .82f, top = .7f, flareT = .3f, lobeAmp = .18f, lobeDecay = .4f, noise = .12f, lean = .12f, jag = 0f, topBump = .12f, tile = 2.4f, sink = .25f; public int K = 28, R = 10, lobes = 5, seed; }
        // Organic mass (RM-1 LumpMesh copy): stacked rings (superellipse footprint, never larger than hw x hd), base lobes spreading like roots, taper, lean, noise-rough sides, bumpy top. Local space, base at y=0.
        static Mesh LumpMesh(LumpP p)
        {
            var rnd = new System.Random(p.seed); float ph = (float)rnd.NextDouble() * 6.283f, nx = (float)rnd.NextDouble() * 80f, nz0 = (float)rnd.NextDouble() * 80f, la = (float)rnd.NextDouble() * 6.283f;
            var lean = new Vector2(Mathf.Cos(la), Mathf.Sin(la)) * p.lean * Mathf.Min(p.hw, p.hd); var verts = new List<Vector3>(); var uvs = new List<Vector2>(); var tris = new List<int>();
            int K = p.K, R = p.R; float perim = Mathf.PI * (p.hw + p.hd);
            for (int j = 0; j <= R; j++)
            {
                float t = j / (float)R, y = Mathf.Lerp(-p.sink, p.h, t);
                float s = Mathf.Lerp(1f, p.body, Smooth(0f, p.flareT, t)) * Mathf.Lerp(1f, p.top, Smooth(p.flareT, 1f, t)); float lamp = p.lobeAmp * (1f - Smooth(0f, p.lobeDecay, t));
                for (int k = 0; k <= K; k++)
                {
                    float th = k / (float)K * 6.2831853f, c = Mathf.Cos(th), sn = Mathf.Sin(th);
                    float rb = Mathf.Pow(Mathf.Pow(Mathf.Abs(c) / p.hw, p.n) + Mathf.Pow(Mathf.Abs(sn) / p.hd, p.n), -1f / p.n);
                    float lobe = 0.5f + 0.5f * Mathf.Cos(p.lobes * th + ph + t * 0.8f);
                    float nv = Mathf.PerlinNoise(nx + c * 1.4f + 5f, nz0 + sn * 1.4f + t * 2.3f);
                    float rad = rb * s * (1f - lamp * (1f - lobe)) * (1f - p.noise * nv);                  // every factor <= 1: the footprint is a hard upper bound
                    float yy = y; if (j == R && p.jag > 0f) yy += p.jag * (Mathf.Abs(Mathf.Sin(th * 2.5f + ph)) * 0.55f - 0.2f);
                    var sh = lean * (t * t);
                    verts.Add(new Vector3(c * rad + sh.x, yy, sn * rad + sh.y)); uvs.Add(new Vector2(k / (float)K * perim / p.tile, (y + p.sink) / p.tile));
                }
            }
            int stride = K + 1; var sideTris = new List<int>();
            for (int j = 0; j < R; j++) for (int k = 0; k < K; k++)
                {
                    int a0 = j * stride + k, a1 = a0 + 1, b0 = a0 + stride, b1 = b0 + 1;
                    sideTris.AddRange(new[] { a0, b0, a1, a1, b0, b1 });
                }
            { var va = verts[sideTris[0]]; var vb = verts[sideTris[1]]; var vc = verts[sideTris[2]]; if (Vector3.Dot(Vector3.Cross(vb - va, vc - va), new Vector3(va.x - lean.x * 0f, 0, va.z)) < 0f) for (int i = 0; i < sideTris.Count; i += 3) { int tmp = sideTris[i + 1]; sideTris[i + 1] = sideTris[i + 2]; sideTris[i + 2] = tmp; } }
            tris.AddRange(sideTris);
            int ringBase = verts.Count; var topRing = new List<Vector3>(); for (int k = 0; k < K; k++) topRing.Add(verts[R * stride + k]);
            var cen = Vector3.zero; foreach (var v in topRing) cen += v; cen /= K; float[] sc = { 1f, .68f, .36f }; int ringsN = sc.Length;
            for (int r = 0; r < ringsN; r++) for (int k = 0; k < K; k++)
                {
                    var v = topRing[k]; var q = new Vector3(Mathf.Lerp(cen.x, v.x, sc[r]), v.y, Mathf.Lerp(cen.z, v.z, sc[r]));
                    float bump = (Mathf.PerlinNoise(nx + q.x * 1.7f, nz0 + q.z * 1.7f) - .45f) * p.topBump * p.h * (r == 0 ? .5f : 1f) * 2f; q.y = Mathf.Max(v.y + bump, v.y - .25f * p.h) + p.h * p.dome * (1f - sc[r] * sc[r]); if (p.jag > 0f && r > 0) q.y -= p.jag * .3f * (r / (float)ringsN);
                    verts.Add(q); uvs.Add(new Vector2(q.x, q.z) / p.tile);
                }
            int centerIdx = verts.Count; verts.Add(new Vector3(cen.x, topRing.Count > 0 ? cen.y - (p.jag > 0f ? p.jag * .35f : -p.topBump * p.h * .25f) : cen.y, cen.z)); uvs.Add(new Vector2(cen.x, cen.z) / p.tile);
            var capTris = new List<int>();
            for (int r = 0; r < ringsN - 1; r++) for (int k = 0; k < K; k++)
                {
                    int k1 = (k + 1) % K; int o0 = ringBase + r * K + k, o1 = ringBase + r * K + k1, i0 = ringBase + (r + 1) * K + k, i1 = ringBase + (r + 1) * K + k1;
                    capTris.AddRange(new[] { o0, i0, o1, o1, i0, i1 });
                }
            for (int k = 0; k < K; k++) { int k1 = (k + 1) % K; capTris.AddRange(new[] { ringBase + (ringsN - 1) * K + k, centerIdx, ringBase + (ringsN - 1) * K + k1 }); }
            for (int i = 0; i < capTris.Count; i += 3) { var va = verts[capTris[i]]; var vb = verts[capTris[i + 1]]; var vc = verts[capTris[i + 2]]; if (Vector3.Cross(vb - va, vc - va).y < 0f) { int tmp = capTris[i + 1]; capTris[i + 1] = capTris[i + 2]; capTris[i + 2] = tmp; } }
            tris.AddRange(capTris);
            var m = new Mesh { name = "Lump", indexFormat = IndexFormat.UInt32 }; m.SetVertices(verts); m.SetUVs(0, uvs); m.SetTriangles(tris, 0); m.RecalculateNormals();
            var nrm = m.normals; for (int j = 0; j <= R; j++) { var n = (nrm[j * stride] + nrm[j * stride + K]).normalized; nrm[j * stride] = n; nrm[j * stride + K] = n; } m.normals = nrm;   // hide the uv seam
            m.RecalculateBounds(); m.RecalculateTangents(); return m;
        }

        // every blocked component inside the slice window is an island (the web grid has no big blocked masses): each tile must show a 3D object; uncovered clusters get a filler placed only on blocked tiles
        static void FillIslands(Transform root, Mats mats, ref int count)
        {
            var seen = new bool[200, 200]; var comps = new List<List<(int, int)>>();
            for (int y = WY0; y < WY1; y++) for (int x = WX0; x < WX1; x++)
                {
                    if (Walk(x, y) || seen[y, x]) continue; var q = new Queue<(int, int)>(); var list = new List<(int, int)>(); q.Enqueue((x, y)); seen[y, x] = true;
                    while (q.Count > 0) { var (cx, cy) = q.Dequeue(); list.Add((cx, cy)); foreach (var (dx, dy) in new[] { (1, 0), (-1, 0), (0, 1), (0, -1) }) { int nx = cx + dx, ny = cy + dy; if (nx < WX0 || ny < WY0 || nx >= WX1 || ny >= WY1 || Walk(nx, ny) || seen[ny, nx]) continue; seen[ny, nx] = true; q.Enqueue((nx, ny)); } }
                    comps.Add(list);
                }
            var poolCover = new HashSet<(int, int)>(); foreach (var pl in build.toxic) for (int i = 0; i < pl.tx.Length; i++) poolCover.Add((pl.tx[i], pl.ty[i]));
            string CoverKind(int tx, int ty)
            {
                float px = (tx + .5f) * T, pz = -(ty + .5f) * T;
                foreach (var f in fps) if (InFP(f, px, pz, 0.6f * T)) return f.kind;
                if (poolCover.Contains((tx, ty))) return "pool";
                return null;
            }
            var rnd = new System.Random(4405); var report = new List<string>(); int id = 0, filled = 0, tilesChecked = 0, tilesUncovered = 0;
            foreach (var comp in comps)
            {
                var covered = new Dictionary<string, int>(); var open = new List<(int, int)>();
                foreach (var (tx, ty) in comp) { var k = CoverKind(tx, ty); tilesChecked++; if (k == null) open.Add((tx, ty)); else covered[k] = covered.TryGetValue(k, out var n) ? n + 1 : 1; }
                int bx0 = 999, by0 = 999, bx1 = -1, by1 = -1; foreach (var (tx, ty) in comp) { bx0 = Mathf.Min(bx0, tx); by0 = Mathf.Min(by0, ty); bx1 = Mathf.Max(bx1, tx); by1 = Mathf.Max(by1, ty); }
                var made = new List<string>(); var openSet = new HashSet<(int, int)>(open); var done = new HashSet<(int, int)>();
                foreach (var t0 in open)
                {
                    if (done.Contains(t0)) continue; var cl = new List<(int, int)>(); var qq = new Queue<(int, int)>(); qq.Enqueue(t0); done.Add(t0);
                    while (qq.Count > 0) { var cur = qq.Dequeue(); cl.Add(cur); for (int dy = -1; dy <= 1; dy++) for (int dx = -1; dx <= 1; dx++) { var nb = (cur.Item1 + dx, cur.Item2 + dy); if (openSet.Contains(nb) && !done.Contains(nb)) { done.Add(nb); qq.Enqueue(nb); } } }
                    float mx = 0, mz = 0; int cx0 = 999, cy0 = 999, cx1 = -1, cy1 = -1; foreach (var (tx, ty) in cl) { mx += (tx + .5f) * T; mz += -(ty + .5f) * T; cx0 = Mathf.Min(cx0, tx); cy0 = Mathf.Min(cy0, ty); cx1 = Mathf.Max(cx1, tx); cy1 = Mathf.Max(cy1, ty); }
                    mx /= cl.Count; mz /= cl.Count; float gy = GroundY(mx, mz);
                    float w = Mathf.Max(0.5f, (cx1 - cx0 + 1) * T * .9f), d = Mathf.Max(0.5f, (cy1 - cy0 + 1) * T * .9f); float yaw = (float)(rnd.NextDouble() - .5) * 30f;
                    var fp = new FP { kind = "island-fill", cx = mx, cz = mz, hw = w * .5f, hd = d * .5f, yaw = yaw }; int sh = 0;
                    while (FpHitsWalk(fp) && sh++ < 10) { w *= .85f; d *= .85f; fp.hw = w * .5f; fp.hd = d * .5f; }
                    if (FpHitsWalk(fp) || w < 0.3f) { made.Add("skipped(no room)"); tilesUncovered += cl.Count; continue; }
                    float rr = Mathf.Sqrt(fp.hw * fp.hw + fp.hd * fp.hd); float dU = WedgeD(mx, mz, rr, out int wtx, out int wty); float hh = Mathf.Min(0.5f + 0.1f * Mathf.Sqrt(cl.Count), 0.97f * HMax(dU));
                    string fname = "Fill_" + (count++).ToString("00"); MakeLump(fname, root, new Vector3(mx, gy, mz), yaw, fp.hw, fp.hd, hh, 7000 + count * 17, mats.Mass, 2.4f, false); fps.Add(fp); made.Add(fname); filled++;
                    wedge.Add(new WedgeRec { name = fname, kind = "fill", h = hh, dU = dU, hMaxU = HMax(dU), tx = wtx, ty = wty, pos = new Vector3(mx, gy, mz) });
                }
                var cov = new List<string>(); foreach (var kv in covered) cov.Add("\"" + kv.Key + "\":" + kv.Value);
                var madeJ = new List<string>(); foreach (var x in made) madeJ.Add("\"" + x + "\"");
                report.Add("{\"id\":" + (id++) + ",\"bbox\":[" + bx0 + "," + by0 + "," + bx1 + "," + by1 + "],\"componentTiles\":" + comp.Count + ",\"coveredBy\":{" + string.Join(",", cov) + "},\"uncoveredTiles\":" + open.Count + ",\"filledBy\":[" + string.Join(",", madeJ) + "]}");
            }
            File.WriteAllText(Root + "/Data/rm4_islands.json", "{\"rule\":\"every blocked tile inside the slice window (x0..199, y32..199) must be covered by a 3D object (lump footprint +0.6 tile, or the toxic pool tiles); uncovered clusters get a filler lump only on blocked tiles\",\"window\":[" + WX0 + "," + WY0 + "," + (WX1 - 1) + "," + (WY1 - 1) + "],\"islands\":" + comps.Count + ",\"blockedTilesChecked\":" + tilesChecked + ",\"uncoveredAfterFill\":" + tilesUncovered + ",\"filledClusters\":" + filled + ",\"items\":[" + string.Join(",", report) + "]}");
            Debug.Log("[RM4] islands=" + comps.Count + " blocked tiles=" + tilesChecked + " filled clusters=" + filled + " uncovered after fill=" + tilesUncovered);
        }

        // Counts walk tiles (slice window) whose centre lies inside a 3D footprint; "deep" = centre at least 0.5 tile inside the footprint edge. Root ridges (terrain relief) are counted separately.
        static void WalkOverlap()
        {
            int any = 0, deep = 0; var byKind = new Dictionary<string, int>(); var tiles = new List<string>();
            for (int ty = WY0; ty < WY1; ty++) for (int tx = WX0; tx < WX1; tx++)
                {
                    if (!Walk(tx, ty)) continue; float px = (tx + .5f) * T, pz = -(ty + .5f) * T; string hit = null; bool dp = false;
                    foreach (var f in fps) if (InFP(f, px, pz, 0f)) { hit = f.kind; dp = InFP(f, px, pz, -0.5f * T); break; }
                    if (hit == null) { var p = new Vector2(px, pz); foreach (var q in ribbonQuads) if (InTri(p, q[0], q[1], q[2]) || InTri(p, q[0], q[2], q[3])) { hit = "river"; dp = true; break; } }
                    if (hit == null) continue; any++; if (dp) deep++; byKind[hit] = byKind.TryGetValue(hit, out var n) ? n + 1 : 1; if (tiles.Count < 400) tiles.Add($"[{tx},{ty},\"{hit}\"]");
                }
            int ridgeTiles = 0; for (int ty = WY0; ty < WY1; ty++) for (int tx = WX0; tx < WX1; tx++) if (Walk(tx, ty) && DistToSegs(ridgeSegs, tx + .5f, ty + .5f) < 1.0f) ridgeTiles++;
            var kinds = new List<string>(); foreach (var kv in byKind) kinds.Add($"\"{kv.Key}\":{kv.Value}");
            File.WriteAllText(Root + "/Data/rm4_walk_overlap.json", "{\"window\":[" + WX0 + "," + WY0 + "," + (WX1 - 1) + "," + (WY1 - 1) + "],\"footprints\":" + fps.Count + ",\"ribbonQuads\":" + ribbonQuads.Count + ",\"walkTilesCoveredCentre\":" + any + ",\"walkTilesCoveredDeep05\":" + deep + ",\"byKind\":{" + string.Join(",", kinds) + "},\"rootRidgeReliefWalkTiles\":" + ridgeTiles + ",\"ridgeNote\":\"terrain relief <=0.10u on walk tiles, no collider, not a lump; reported separately\",\"tiles\":[" + string.Join(",", tiles) + "]}");
            Debug.Log($"[RM4] walk overlap centre={any} deep(>=0.5 tile)={deep} ridgeReliefWalkTiles={ridgeTiles}");
        }

        // ---------------------------------------------------------------- W5/W4: grass (clustered, darker than the floor) + procedural alpha cards
        static Color32 Lerp32(Color a, Color b, float t) { return (Color32)Color.Lerp(a, b, t); }
        static void AddGrass(TerrainData td)
        {
            var path = GenDir + "/grass_blade_proc.png"; const int S = 128; var px = new Color32[S * S];
            Color baseC = new Color(.06f, .04f, .035f), tipC = new Color(.25f, .135f, .105f);
            var rnd = new System.Random(77);
            for (int b = 0; b < 7; b++)
            {
                float x0 = 24 + b * 13f + (float)rnd.NextDouble() * 6f, dx = ((float)rnd.NextDouble() - .5f) * 46f, tip = 70f + (float)rnd.NextDouble() * 48f, w0 = 4.2f + (float)rnd.NextDouble() * 2f;
                for (int k = 0; k <= 80; k++)
                {
                    float t = k / 80f; float cx = x0 + dx * Mathf.Pow(t, 1.6f), cy = tip * t, r = Mathf.Max(0.6f, w0 * Mathf.Pow(1f - t, .8f));
                    var col = Lerp32(baseC, tipC, Mathf.Clamp01(t * 1.15f));
                    for (int yy = -6; yy <= 6; yy++) for (int xx = -6; xx <= 6; xx++)
                        {
                            int X = Mathf.RoundToInt(cx) + xx, Y = Mathf.RoundToInt(cy) + yy; if (X < 0 || Y < 0 || X >= S || Y >= S) continue;
                            float d = Mathf.Sqrt(xx * xx + yy * yy); if (d > r) continue; float a = Mathf.Clamp01((r - d) * 1.5f);
                            var o = px[Y * S + X]; if (a * 255f > o.a) { col.a = (byte)(a * 255f); px[Y * S + X] = col; }
                        }
                }
            }
            for (int x = 0; x < S; x++) for (int y = 0; y < 14; y++) { var o = px[y * S + x]; if (o.a == 0) continue; float ao = Mathf.Lerp(.55f, 1f, y / 14f); px[y * S + x] = new Color32((byte)(o.r * ao), (byte)(o.g * ao), (byte)(o.b * ao), o.a); }
            var tex = new Texture2D(S, S, TextureFormat.RGBA32, false); tex.SetPixels32(px); File.WriteAllBytes(path, tex.EncodeToPNG()); UnityEngine.Object.DestroyImmediate(tex); AssetDatabase.ImportAsset(path);
            var ti = AssetImporter.GetAtPath(path) as TextureImporter; if (ti != null) { ti.alphaIsTransparency = true; ti.wrapMode = TextureWrapMode.Clamp; ti.mipmapEnabled = false; ti.SaveAndReimport(); }
            var dp = new DetailPrototype { prototypeTexture = AssetDatabase.LoadAssetAtPath<Texture2D>(path), usePrototypeMesh = false, renderMode = DetailRenderMode.GrassBillboard, minWidth = .30f, maxWidth = .52f, minHeight = .32f, maxHeight = .55f, noiseSpread = .35f,
                healthyColor = new Color(1f, .94f, .90f), dryColor = new Color(.82f, .84f, .68f) };
            const int DR = 512; td.detailPrototypes = new[] { dp }; td.SetDetailResolution(DR, 16);
            var map = new int[DR, DR]; int used = 0;
            for (int i = 0; i < DR; i++) for (int j = 0; j < DR; j++)
                {
                    float X = TX0 + (TX1 - TX0) * (j / (float)(DR - 1)), Y = TY1 - (TY1 - TY0) * (i / (float)(DR - 1));
                    if (!Walk(Mathf.FloorToInt(X), Mathf.FloorToInt(Y))) continue;
                    float n = Mathf.PerlinNoise(X * .11f + 5f, Y * .11f + 9f) * .65f + Mathf.PerlinNoise(X * .37f, Y * .37f) * .35f;   // clustered: only inside high-noise patches
                    if (n > .76f && Hash(i, j) < .15f) { map[i, j] = 1 + (Hash(j, i) < .4f ? 1 : 0); used++; }
                }
            td.SetDetailLayer(0, 0, 0, map); td.wavingGrassStrength = .35f; td.wavingGrassAmount = .3f; td.wavingGrassSpeed = .5f;
            Debug.Log("[RM4] grass clumps=" + used);
        }
        // procedural alpha card (blurred): fg = hanging/rising root tangles, bg = dead-tree silhouettes fading into haze
        static Texture2D ProcCard(string path, int seed, bool fg)
        {
            const int S = 256; var a = new float[S * S]; var rnd = new System.Random(seed);
            void Stamp(float cx, float cy, float r, float v) { int ri = Mathf.CeilToInt(r) + 1; for (int yy = -ri; yy <= ri; yy++) for (int xx = -ri; xx <= ri; xx++) { int X = Mathf.RoundToInt(cx) + xx, Y = Mathf.RoundToInt(cy) + yy; if (X < 0 || Y < 0 || X >= S || Y >= S) continue; float d = Mathf.Sqrt(xx * xx + yy * yy); if (d > r) continue; int ix = Y * S + X; a[ix] = Mathf.Max(a[ix], v * Mathf.Clamp01((r - d) * 1.2f)); } }
            void Branch(Vector2 p, float ang, float len, float w, int depth)
            {
                int steps = Mathf.Max(6, (int)len); for (int k = 0; k < steps; k++) { float t = k / (float)steps; p += new Vector2(Mathf.Cos(ang), Mathf.Sin(ang)); ang += ((float)rnd.NextDouble() - .5f) * (fg ? .5f : .22f); Stamp(p.x, p.y, Mathf.Max(1.3f, w * (1f - t * .8f)), 1f); if (depth > 0 && rnd.NextDouble() < (fg ? .035 : .05)) Branch(p, ang + ((float)rnd.NextDouble() - .5f) * 1.7f, len * .55f, w * .6f, depth - 1); }
            }
            if (fg) { for (int r = 0; r < 6; r++) Branch(new Vector2(30 + r * 38 + (float)rnd.NextDouble() * 20, 0), 1.45f + ((float)rnd.NextDouble() - .5f) * .9f, 120 + (float)rnd.NextDouble() * 80, 9 + (float)rnd.NextDouble() * 6, 3); }
            else { Branch(new Vector2(S * .5f, 0), 1.5708f + ((float)rnd.NextDouble() - .5f) * .08f, 150, 11, 4); Branch(new Vector2(S * .5f + 4, 60), 1.0f, 70, 5, 2); Branch(new Vector2(S * .5f - 4, 85), 2.15f, 70, 5, 2); }
            for (int pass = 0; pass < 2; pass++)   // two box blurs (radius 3) = out-of-focus layer
            {
                var t = new float[S * S];
                for (int y = 0; y < S; y++) for (int x = 0; x < S; x++) { float sum = 0; int n = 0; for (int k = -3; k <= 3; k++) { int X = Mathf.Clamp(x + k, 0, S - 1); sum += a[y * S + X]; n++; } t[y * S + x] = sum / n; }
                for (int y = 0; y < S; y++) for (int x = 0; x < S; x++) { float sum = 0; int n = 0; for (int k = -3; k <= 3; k++) { int Y = Mathf.Clamp(y + k, 0, S - 1); sum += t[Y * S + x]; n++; } a[y * S + x] = sum / n; }
            }
            var px = new Color32[S * S];
            for (int y = 0; y < S; y++) for (int x = 0; x < S; x++) { float v = a[y * S + x] * (fg ? 1f : Mathf.Lerp(.35f, 1f, y / (float)S)); float edge = Mathf.Clamp01(Mathf.Min(Mathf.Min(x, S - 1 - x), S - 1 - y) / 10f); px[y * S + x] = new Color32(255, 255, 255, (byte)(Mathf.Clamp01(v) * edge * 255f)); }
            var tex = new Texture2D(S, S, TextureFormat.RGBA32, false); tex.SetPixels32(px); File.WriteAllBytes(path, tex.EncodeToPNG()); UnityEngine.Object.DestroyImmediate(tex); AssetDatabase.ImportAsset(path);
            var ti = AssetImporter.GetAtPath(path) as TextureImporter; if (ti != null) { ti.alphaIsTransparency = true; ti.wrapMode = TextureWrapMode.Clamp; ti.mipmapEnabled = false; ti.SaveAndReimport(); }
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }
        // far layer: dead-tree silhouette cards beyond the west/east rim lumps, never south of the walk area (they must not block the camera view of the combat floor)
