            File.WriteAllText(Root + "/Data/rm4_hero_layer.json", "{\"renderers\":" + total + ",\"nonDefaultRenderingLayerMask\":" + nonDefault + ",\"note\":\"every map renderer keeps the default rendering layer (mask 1); the Hero layer is never used\"}");
            Debug.Log("[RM4] renderers=" + total + " non-default rendering layer=" + nonDefault);
        }
        static void WriteWedgeCandidates()
        {
            var items = new List<string>(); foreach (var w in wedge) items.Add("{\"name\":\"" + w.name + "\",\"kind\":\"" + w.kind + "\",\"h\":" + w.h.ToString("F2") + ",\"D_u\":" + w.dU.ToString("F2") + ",\"hMax_u\":" + w.hMaxU.ToString("F2") + ",\"northWalkTile\":[" + w.tx + "," + w.ty + "]}");
            File.WriteAllText(Root + "/Data/rm4_wedge_candidates.json", "{\"rule\":\"h <= 0.9 + tan(0.85) * D; D = lump north end to the nearest walkable tile centre north of it (u)\",\"count\":" + wedge.Count + ",\"items\":[" + string.Join(",", items) + "]}");
        }
        // sight-wedge check: for every lump with a walk tile north of it, stand the capsule (1.6u) on that tile with the game camera and cast rays to its head and body. Colliders are added at runtime only (the scene is not saved).
        public static void Wedge()
        {
            AudioListener.volume = 0f; Load(); EditorSceneManager.OpenScene(ScenePath);
            var marker = GameObject.Find("Player Marker").transform; var brain = UnityEngine.Object.FindFirstObjectByType<CinemachineBrain>(); var cam = Camera.main; terrain = UnityEngine.Object.FindFirstObjectByType<Terrain>();
            var cand = JsonUtility.FromJson<WedgeFile>(File.ReadAllText(Root + "/Data/rm4_wedge_candidates.json"));
            foreach (var mf in GameObject.Find("Blockout").GetComponentsInChildren<MeshFilter>()) if (mf.GetComponent<Collider>() == null) mf.gameObject.AddComponent<MeshCollider>();
            Physics.SyncTransforms(); var res = new List<string>(); int tested = 0, fail = 0, over09 = 0, over09fail = 0;
            foreach (var it in cand.items)
            {
                if (it.northWalkTile == null || it.northWalkTile.Length < 2 || it.northWalkTile[0] < 0) continue;
                var w = W(it.northWalkTile[0] + .5f, it.northWalkTile[1] + .5f); float gy = GroundY(w.x, w.z); marker.position = new Vector3(w.x, gy, w.z); brain.ManualUpdate(); Physics.SyncTransforms();
                var cp = cam.transform.position; bool headHit = Physics.Linecast(cp, new Vector3(w.x, gy + 1.6f, w.z), out var hh); bool bodyHit = Physics.Linecast(cp, new Vector3(w.x, gy + 0.8f, w.z), out var bh);
                string by = headHit ? hh.collider.name : (bodyHit ? bh.collider.name : ""); bool pass = !headHit && !bodyHit; tested++; if (!pass) fail++; bool big = it.h > 0.9f; if (big) { over09++; if (!pass) over09fail++; }
                res.Add("{\"name\":\"" + it.name + "\",\"h\":" + it.h.ToString("F2") + ",\"D_u\":" + it.D_u.ToString("F2") + ",\"hMax_u\":" + it.hMax_u.ToString("F2") + ",\"over0_9\":" + (big ? "true" : "false") + ",\"tile\":[" + it.northWalkTile[0] + "," + it.northWalkTile[1] + "],\"headVisible\":" + (!headHit ? "true" : "false") + ",\"bodyVisible\":" + (!bodyHit ? "true" : "false") + ",\"blockedBy\":\"" + by + "\",\"pass\":" + (pass ? "true" : "false") + "}");
            }
            // terrain sweep (lumps are not the only occluders): every walk tile with a non-walk tile directly north, same capsule rays; only TerrainCollider hits count here (lump hits are listed above)
            int tEdge = 0, tFail = 0; var tList = new List<string>();
            for (int ty = WY0; ty < WY1; ty++) for (int tx = WX0; tx < WX1; tx++)
                {
                    if (!Walk(tx, ty) || Walk(tx, ty - 1)) continue;
                    var tw = W(tx + .5f, ty + .5f); float tg = GroundY(tw.x, tw.z); marker.position = new Vector3(tw.x, tg, tw.z); brain.ManualUpdate();
                    var tcp = cam.transform.position; bool th = Physics.Linecast(tcp, new Vector3(tw.x, tg + 1.6f, tw.z), out var thit) && thit.collider is TerrainCollider; bool tb = Physics.Linecast(tcp, new Vector3(tw.x, tg + 0.8f, tw.z), out var tbit) && tbit.collider is TerrainCollider;
                    tEdge++; if (th || tb) { tFail++; if (tList.Count < 60) tList.Add("[" + tx + "," + ty + "]"); }
                }
            File.WriteAllText(Root + "/Data/rm4_wedge_terrain.json", "{\"rule\":\"walk tiles with a non-walk tile directly north: capsule 1.6u rays to head and body must not hit the TerrainCollider\",\"tested\":" + tEdge + ",\"failed\":" + tFail + ",\"firstFailedTiles\":\"" + string.Join("", tList) + "\"}");
            Debug.Log("[RM4] wedge terrain edge tiles=" + tEdge + " failed=" + tFail);
            File.WriteAllText(Root + "/Data/rm4_wedge.json", "{\"rule\":\"capsule 1.6u on the walk tile north of each lump, game camera, rays to head (1.6u) and body (0.8u) must reach it\",\"tested\":" + tested + ",\"failed\":" + fail + ",\"lumpsOver0_9u\":" + over09 + ",\"lumpsOver0_9uFailed\":" + over09fail + ",\"items\":[" + string.Join(",", res) + "]}");
            Debug.Log("[RM4] wedge tested=" + tested + " failed=" + fail + " over0.9u=" + over09 + " over0.9uFailed=" + over09fail);
        }
        [Serializable] class WedgeItem { public string name, kind; public float h, D_u, hMax_u; public int[] northWalkTile; }
        [Serializable] class WedgeFile { public WedgeItem[] items; }

        // ---------------------------------------------------------------- FPS: same START view, 3D layer (World root) on vs off, 1600x900, 240 frames each
        public static void Fps()
        {
            var args = Environment.GetCommandLineArgs(); string Arg(string k, string d) { int i = Array.IndexOf(args, k); return i >= 0 ? args[i + 1] : d; }
            var outJson = Arg("-out", Out("rm4-fps.json")); AudioListener.volume = 0f; Load(); EditorSceneManager.OpenScene(ScenePath);
            var marker = GameObject.Find("Player Marker").transform; var cam = Camera.main; var brain = UnityEngine.Object.FindFirstObjectByType<CinemachineBrain>(); terrain = UnityEngine.Object.FindFirstObjectByType<Terrain>();
            var w0 = W(100f, 185f); marker.position = new Vector3(w0.x, GroundY(w0.x, w0.z), w0.z); brain.ManualUpdate(); var cull = UnityEngine.Object.FindFirstObjectByType<Rm4PoolLightCuller>(); if (cull != null) cull.Refresh(marker.position);
            var world = GameObject.Find("World"); var rt = new RenderTexture(1600, 900, 24, RenderTextureFormat.ARGB32) { antiAliasing = 4 }; cam.targetTexture = rt;
            var tex = new Texture2D(4, 4, TextureFormat.RGB24, false); var res = new List<string>();
            foreach (var on in new[] { true, false, true })
            {
                world.SetActive(on); for (int i = 0; i < 20; i++) cam.Render(); RenderTexture.active = rt; tex.ReadPixels(new Rect(0, 0, 4, 4), 0, 0);
                var sw = System.Diagnostics.Stopwatch.StartNew(); const int N = 240; for (int i = 0; i < N; i++) cam.Render(); RenderTexture.active = rt; tex.ReadPixels(new Rect(0, 0, 4, 4), 0, 0); sw.Stop();
                res.Add("{\"world3d\":" + (on ? "true" : "false") + ",\"frames\":" + N + ",\"ms\":" + sw.ElapsedMilliseconds + ",\"fps\":" + (N * 1000.0 / sw.ElapsedMilliseconds).ToString("F1") + "}");
            }
            RenderTexture.active = null; cam.targetTexture = null; Directory.CreateDirectory(Path.GetDirectoryName(outJson) ?? "."); File.WriteAllText(outJson, "{\"gpu\":\"" + SystemInfo.graphicsDeviceName + "\",\"note\":\"batchmode camera.Render loop (editor), no vsync cap; relative on/off comparison\",\"runs\":[" + string.Join(",", res) + "]}");
            Debug.Log("[RM4] fps done " + string.Join(" ", res));
        }

        // ---------------------------------------------------------------- capture
        public static void Capture()
        {
            var args = Environment.GetCommandLineArgs(); string Arg(string k, string d) { int i = Array.IndexOf(args, k); return i >= 0 ? args[i + 1] : d; }
            var outDir = Arg("-outDir", "I:/EXODUSER-Storage/rm4/cuts"); Directory.CreateDirectory(outDir);
            var cuts = Arg("-cuts", "start,heart,gate").Split(',');
            AudioListener.volume = 0f; Load(); EditorSceneManager.OpenScene(ScenePath);
            var marker = GameObject.Find("Player Marker").transform; var cam = Camera.main; var brain = UnityEngine.Object.FindFirstObjectByType<CinemachineBrain>(); terrain = UnityEngine.Object.FindFirstObjectByType<Terrain>();
            var cull = UnityEngine.Object.FindFirstObjectByType<Rm4PoolLightCuller>();
            var focus = new Dictionary<string, Vector2> { { "start", new Vector2(100f, 185f) }, { "heart", new Vector2(100f, 70f) }, { "gate", new Vector2(100f, 38f) } };
            bool ridgeCut = Array.IndexOf(cuts, "ridge") >= 0; bool capsule = Arg("-capsule", "0") == "1" || ridgeCut;   // the ridge cut needs the capsule; run it alone: -cuts ridge
            if (capsule)
            {   // player-size stand-in (1.6u tall, 0.5u wide) to judge occlusion; hides the sandbox marker sprite
                var ms = marker.Find("Marker Sprite"); if (ms != null) ms.gameObject.SetActive(false);
                var cap = GameObject.CreatePrimitive(PrimitiveType.Capsule); cap.name = "Capture Capsule"; cap.transform.SetParent(marker, false); cap.transform.localPosition = new Vector3(0, 0.8f, 0); cap.transform.localScale = new Vector3(0.5f, 0.8f, 0.5f);
                UnityEngine.Object.DestroyImmediate(cap.GetComponent<Collider>());
                var cm = new Material(Shader.Find("Universal Render Pipeline/Lit")); cm.SetColor("_BaseColor", new Color(.25f, .85f, .95f)); cap.GetComponent<MeshRenderer>().sharedMaterial = cm;
            }
            foreach (var cut in cuts)
            {
                if (cut == "top") { CaptureTop(outDir); continue; }
                if (cut == "ridge") { CaptureRidge(outDir, marker, cam, brain, cull); continue; }
                if (!focus.TryGetValue(cut, out var f)) continue;
                var w = W(f.x, f.y); marker.position = new Vector3(w.x, GroundY(w.x, w.z), w.z); if (cull != null) cull.Refresh(marker.position);
                var rt = new RenderTexture(1600, 900, 24, RenderTextureFormat.ARGB32) { antiAliasing = 4 }; cam.targetTexture = rt;
                brain.ManualUpdate(); cam.Render();
                RenderTexture.active = rt; var tex = new Texture2D(1600, 900, TextureFormat.RGB24, false); tex.ReadPixels(new Rect(0, 0, 1600, 900), 0, 0); tex.Apply();
                File.WriteAllBytes(Path.Combine(outDir, "rm4_" + cut + (capsule ? "_cap" : "") + ".png"), tex.EncodeToPNG()); RenderTexture.active = null; cam.targetTexture = null;
                UnityEngine.Object.DestroyImmediate(tex); rt.Release();
                Debug.Log("[RM4] captured " + cut);
            }
        }
        // walk tile on a root-ridge crest nearest the heart; capsule stands once at y=0 (what the runtime does: no terrain lift) and once on the terrain (GroundY), side by side in two files
        static void CaptureRidge(string outDir, Transform marker, Camera cam, CinemachineBrain brain, Rm4PoolLightCuller cull)
        {
            int bx = -1, by = -1; float best = 1e9f;
            for (int ty = WY0; ty < WY1; ty++) for (int tx = WX0; tx < WX1; tx++)
                {
                    if (!Walk(tx, ty)) continue;
                    float rd = DistToSegs(ridgeSegs, tx + .5f, ty + .5f); if (rd > 0.25f) continue;
                    float sc = rd * 40f + Mathf.Abs(tx - 100) + Mathf.Abs(ty - 70) * 0.5f; if (sc < best) { best = sc; bx = tx; by = ty; }
                }
            if (bx < 0) { Debug.LogError("[RM4] ridge cut: no walk tile on a ridge crest"); return; }
            var w = W(bx + .5f, by + .5f); float gy = GroundY(w.x, w.z);
            Debug.Log("[RM4] ridge cut tile " + bx + "," + by + " groundY=" + gy.ToString("F3") + " (feet at y=0 are buried by " + Mathf.Max(0f, gy).ToString("F3") + "u)");
            File.WriteAllText(Root + "/Data/rm4_ridge_cut.json", "{\"tile\":[" + bx + "," + by + "],\"groundY\":" + gy.ToString("F4", System.Globalization.CultureInfo.InvariantCulture) + "}");
            foreach (var v in new[] { "y0", "ground" })
            {
                marker.position = new Vector3(w.x, v == "y0" ? 0f : gy, w.z); if (cull != null) cull.Refresh(marker.position);
                var rt = new RenderTexture(1600, 900, 24, RenderTextureFormat.ARGB32) { antiAliasing = 4 }; cam.targetTexture = rt;
                brain.ManualUpdate(); cam.Render();
                RenderTexture.active = rt; var tex = new Texture2D(1600, 900, TextureFormat.RGB24, false); tex.ReadPixels(new Rect(0, 0, 1600, 900), 0, 0); tex.Apply();
                File.WriteAllBytes(Path.Combine(outDir, "rm4_ridge_" + v + ".png"), tex.EncodeToPNG()); RenderTexture.active = null; cam.targetTexture = null;
                UnityEngine.Object.DestroyImmediate(tex); rt.Release();
            }
            Debug.Log("[RM4] captured ridge");
        }
        // orthographic top view of the slice window (x0..199 y32..199) with the Core walk tiles overlaid in translucent green
        static void CaptureTop(string outDir)
        {
            var cam = Camera.main; var brain = UnityEngine.Object.FindFirstObjectByType<CinemachineBrain>(); if (brain != null) brain.enabled = false;
            const int Wpx = 3200, Hpx = 2688; const float x0 = WX0 * T, x1 = WX1 * T, zN = -WY0 * T, zS = -WY1 * T;
            cam.orthographic = true; cam.orthographicSize = (zN - zS) * .5f; cam.nearClipPlane = 0.1f; cam.farClipPlane = 200f;
            cam.transform.SetPositionAndRotation(new Vector3((x0 + x1) * .5f, 60f, (zN + zS) * .5f), Quaternion.Euler(90f, 0f, 0f));
            var rt = new RenderTexture(Wpx, Hpx, 24, RenderTextureFormat.ARGB32) { antiAliasing = 4 }; cam.targetTexture = rt; cam.Render();
            RenderTexture.active = rt; var tex = new Texture2D(Wpx, Hpx, TextureFormat.RGB24, false); tex.ReadPixels(new Rect(0, 0, Wpx, Hpx), 0, 0);
            var px = tex.GetPixels32();
            for (int r = 0; r < Hpx; r++) for (int c = 0; c < Wpx; c++)
                {
                    float wx = x0 + (c + .5f) / Wpx * (x1 - x0), wz = zS + (r + .5f) / Hpx * (zN - zS); int tx = Mathf.FloorToInt(wx / T), ty = Mathf.FloorToInt(-wz / T);
                    if (!Walk(tx, ty)) continue; var p = px[r * Wpx + c]; p.r = (byte)(p.r * .62f + 40 * .38f); p.g = (byte)(p.g * .62f + 255 * .38f); p.b = (byte)(p.b * .62f + 60 * .38f); px[r * Wpx + c] = p;
                }
            tex.SetPixels32(px); tex.Apply();
            File.WriteAllBytes(Path.Combine(outDir, "rm4_top_walk_overlay.png"), tex.EncodeToPNG()); RenderTexture.active = null; cam.targetTexture = null;
            UnityEngine.Object.DestroyImmediate(tex); rt.Release(); Debug.Log("[RM4] captured top");
        }
    }
